def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'D'
    if n == 2:
        opp_defs = sum(1 for h in history if h[1] == 'D')
        if opp_defs > 0:
            return 'D'
        return 'C'

    if n == 99:
        return 'D'

    opp_moves = [h[1] for h in history]
    opp_defs = sum(1 for o in opp_moves if o == 'D')
    last_opp = opp_moves[-1]

    if opp_defs == 0:
        return 'D'

    if last_opp == 'D':
        recent_opp = opp_moves[-2:]
        if recent_opp.count('D') >= 2:
            return 'D'
        else:
            return 'C'
    else:
        return 'C'
